      try { if (typeof console !== "undefined" && console.warn) console.warn("[ATYAB] referral-rejected", rc, data); } catch (eLR) {}      try { markSetupRejected(aPid || undefined, rc); } catch (eMR) {}
      /* ★ OP2 §5: الزيارة المستهلَكة ميتة — تُمسح فوراً (إن كانت الحالية). */
